,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    IF :CHECK_IN IS NOT NULL THEN',
'        IF TO_NUMBER(TO_CHAR(TO_DATE(:CHECK_IN, ''DD-MON-YYYY HH24:MI''), ''HH24MI'')) > 900 THEN',
'            :LATE_MINUTES := (TO_DATE(:CHECK_IN, ''DD-MON-YYYY HH24:MI'') - (TRUNC(TO_DATE(:CHECK_IN, ''DD-MON-YYYY HH24:MI'')) + 9/24)) * 24 * 60;',
'            :STATUS := ''LATE'';',
'        ELSE',
'            :LATE_MINUTES := 0;',
'            :STATUS := ''PRESENT'';',
'        END IF;',
'    END IF;',
'END;'))
