,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Approve Leave'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
unistr('    -- 1. \062A\062D\062F\064A\062B \062D\0627\0644\0629 \0627\0644\0637\0644\0628 \0625\0644\0649 APPROVED'),
'    UPDATE hr_leaves',
'    SET status = ''APPROVED''',
'    WHERE leave_id = :P10_LEAVE_ID;',
'',
unistr('    -- 2. \062E\0635\0645 \0627\0644\0623\064A\0627\0645 \0645\0646 \0631\0635\064A\062F \0627\0644\0645\0648\0638\0641 (\062A\063A\0644\064A\0641 \0628\0640 Exception \0644\0645\0646\0639 \0627\0644\062E\0637\0623 \0625\0646 \0644\0645 \062A\0643\0646 \0627\0644\0631\0635\064A\062F \0645\0648\062C\0648\062F\0629)'),
'    BEGIN',
'        UPDATE hr_leave_balances',
'        SET used_days = NVL(used_days, 0) + NVL(:P10_TOTAL_DAYS, 1)',
'        WHERE employee_id = :P10_EMPLOYEE_ID',
'          AND leave_type_id = :P10_LEAVE_TYPE_ID;',
'    EXCEPTION',
'        WHEN OTHERS THEN',
'            NULL;',
'    END;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(14418760516049050)
,p_internal_uid=>13504859137290743
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(13504949600290744)
,p_process_sequence=>30
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Reject Leave'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    UPDATE hr_leaves',
'    SET status = ''REJECTED''',
'    WHERE leave_id = :P10_LEAVE_ID;',
'END;'))
,p_process_clob_language=>'PLSQL'
