,p_plug_display_sequence=>10
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ',
'    employee_id,',
'    employee_code,',
'    full_name,',
'    email,',
'    phone,',
'    department_name,',
'    designation_title,',
'    branch_name,',
'    manager_name,',
'    joining_date,',
'    basic_salary,',
'    gross_salary,',
'    status,',
'    ''https://api.qrserver.com/v1/create-qr-code/?size=100x100&data='' || ',
'    APEX_UTIL.URL_ENCODE(''Code: '' || employee_code || chr(10) || ''Name: '' || full_name || chr(10) || ''Title: '' || designation_title) AS qr_code_url',
'FROM v_hr_employee_details',
'WHERE (',
'    hr_security_pkg.user_has_role(:APP_USER, ''ADMIN'') = ''Y''',
'    OR hr_security_pkg.user_has_role(:APP_USER, ''HR_MANAGER'') = ''Y''',
'    OR department_name IN (',
'        SELECT d.department_name ',
'        FROM hr_departments d ',
'        JOIN hr_users u ON d.manager_id = u.employee_id ',
'        WHERE UPPER(u.username) = UPPER(:APP_USER)',
'    )',
')'))
,p_plug_source_type=>'NATIVE_IR'
,p_prn_page_header=>'Employees'
);
