wwv_flow_imp_page.create_page_validation(
 p_id=>wwv_flow_imp.id(13503985881290734)
,p_validation_name=>'Check Available Balance'
,p_validation_sequence=>180
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_available_balance NUMBER := 0;',
'    v_emp_id            NUMBER;',
'    v_year              NUMBER;',
'BEGIN',
unistr('    -- 1. \062A\062D\062F\064A\062F \0631\0642\0645 \0627\0644\0645\0648\0638\0641 \0645\0646 \0627\0644\0639\0646\0635\0631 \0645\0628\0627\0634\0631\0629 \0623\0648 \0645\0646 \0627\0644\064A\0648\0632\0631'),
'    v_emp_id := NVL(:P13_EMPLOYEE_ID, 0);',
'    ',
'    IF v_emp_id = 0 THEN',
'        BEGIN',
'            SELECT employee_id INTO v_emp_id',
'            FROM hr_users',
'            WHERE UPPER(username) = UPPER(:APP_USER);',
'        EXCEPTION',
'            WHEN OTHERS THEN v_emp_id := NULL;',
'        END;',
'    END IF;',
'',
unistr('    -- 2. \0627\0633\062A\062E\0631\0627\062C \0627\0644\0633\0646\0629 \0628\0623\0645\0627\0646 \062F\0648\0646 \0627\0644\062A\064A\062F \0628\062A\0646\0633\064A\0642 \0645\062D\062F\062F'),
'    BEGIN',
'        v_year := EXTRACT(YEAR FROM TO_DATE(:P13_START_DATE, NVL(SYS_CONTEXT(''APEX$SESSION'', ''APP_DATE_FORMAT''), ''MM/DD/YYYY'')));',
'    EXCEPTION',
'        WHEN OTHERS THEN',
'            v_year := EXTRACT(YEAR FROM SYSDATE);',
'    END;',
'',
unistr('    -- 3. \062C\0644\0628 \0627\0644\0631\0635\064A\062F \0627\0644\0645\062A\0627\062D'),
'    SELECT (entitled_days - NVL(used_days, 0) - NVL(pending_days, 0))',
'    INTO v_available_balance',
'    FROM hr_leave_balances',
'    WHERE employee_id = v_emp_id',
'      AND leave_type_id = :P13_LEAVE_TYPE_ID',
'      AND year = v_year;',
'',
unistr('    -- 4. \0627\0644\062A\062D\0642\0642 \0645\0646 \0643\0641\0627\064A\0629 \0627\0644\0631\0635\064A\062F'),
'    IF NVL(:P13_TOTAL_DAYS, 0) > v_available_balance THEN',
unistr('        RETURN ''\0639\0630\0631\0627\064B! \0631\0635\064A\062F \0625\062C\0627\0632\0627\062A\0643 \0627\0644\0645\062A\0627\062D \0647\0648 ('' || v_available_balance || '') \064A\0648\0645 \0641\0642\0637\060C \0648\0644\0627 \064A\0643\0641\064A \0644\0637\0644\0628 ('' || :P13_TOTAL_DAYS || '') \064A\0648\0645.'';'),
'    END IF;',
'',
'    RETURN NULL;',
'EXCEPTION',
'    WHEN NO_DATA_FOUND THEN',
unistr('        RETURN ''\0644\0645 \064A\062A\0645 \0625\0639\062F\0627\062F \0631\0635\064A\062F \0625\062C\0627\0632\0627\062A \0644\0647\0630\0627 \0627\0644\0645\0648\0638\0641 \0644\0644\0633\0646\0629 \0627\0644\062D\0627\0644\064A\0629.'';'),
'    WHEN OTHERS THEN',
'        RETURN NULL;',
'END;'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_ERR_TEXT'
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
);
