wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(13504074915290735)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Submit Leave via Package'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- DECLARE',
'--     v_emp_id   NUMBER;',
'--     v_leave_id NUMBER;',
'-- BEGIN',
'--     SELECT employee_id INTO v_emp_id ',
'--     FROM hr_users ',
'--     WHERE UPPER(username) = UPPER(:APP_USER);',
'',
'--     hr_leave_workflow_pkg.submit_leave_request(',
'--         p_employee_id   => v_emp_id,',
'--         p_leave_type_id => :P13_LEAVE_TYPE_ID,',
'--         p_start_date    => TO_DATE(:P13_START_DATE, ''YYYY-MM-DD''),',
'--         p_end_date      => TO_DATE(:P13_END_DATE, ''YYYY-MM-DD''),',
'--         p_reason        => :P13_REASON,',
'--         p_out_leave_id  => v_leave_id',
'--     );',
'-- END;',
'DECLARE',
'    v_emp_id NUMBER;',
'BEGIN',
unistr('    -- \062C\0644\0628 \0631\0642\0645 \0627\0644\0645\0648\0638\0641 \0645\0646 \0627\0644\0639\0646\0627\0635\0631 \0623\0648 \0627\0644\064A\0648\0632\0631'),
'    v_emp_id := :P13_EMPLOYEE_ID;',
'    ',
'    IF v_emp_id IS NULL THEN',
'        BEGIN',
'            SELECT employee_id INTO v_emp_id',
'            FROM hr_users',
'            WHERE UPPER(username) = UPPER(:APP_USER);',
'        EXCEPTION',
'            WHEN OTHERS THEN',
'                SELECT employee_id INTO v_emp_id FROM hr_employees WHERE ROWNUM = 1;',
'        END;',
'    END IF;',
'',
unistr('    -- \0627\0644\0625\062F\0631\0627\062C \0627\0644\0645\0628\0627\0634\0631 \0641\064A \0627\0644\062C\062F\0648\0644 \0627\0644\0635\062D\064A\062D'),
'    INSERT INTO hr_leaves (',
'        employee_id,',
'        leave_type_id,',
'        start_date,',
'        end_date,',
'        total_days,',
'        reason,',
'        status',
'    ) VALUES (',
'        v_emp_id,',
'        :P13_LEAVE_TYPE_ID,',
'        TO_DATE(:P13_START_DATE, NVL(SYS_CONTEXT(''APEX$SESSION'', ''APP_DATE_FORMAT''), ''MM/DD/YYYY'')),',
'        TO_DATE(:P13_END_DATE, NVL(SYS_CONTEXT(''APEX$SESSION'', ''APP_DATE_FORMAT''), ''MM/DD/YYYY'')),',
'        NVL(:P13_TOTAL_DAYS, 1),',
'        :P13_REASON,',
'        ''PENDING''',
'    );',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_success_message=>unistr('\062A\0645 \062A\0642\062F\064A\0645 \0637\0644\0628 \0627\0644\0625\062C\0627\0632\0629 \0628\0646\062C\0627\062D \0648\0647\0648 \0642\064A\062F \0645\0631\0627\062C\0639\0629 \0627\0644\0645\062F\064A\0631')
,p_internal_uid=>13504074915290735
);
