,p_title=>'Employee Timeline'
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>3371237801798025892
,p_plug_display_sequence=>20
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('-- \062A\0627\0631\064A\062E \0627\0644\062A\0639\064A\064A\0646'),
'SELECT ',
'    ''Joined Company'' AS title,',
'    ''Employee officially joined as '' || designation_title AS description,',
'    joining_date AS event_date,',
'    ''fa-user-plus'' AS icon,',
'    ''u-color-1'' AS css_class',
'FROM v_hr_employee_details',
'WHERE employee_id = :P14_EMPLOYEE_ID',
'',
'UNION ALL',
'',
unistr('-- \0637\0644\0628\0627\062A \0627\0644\0625\062C\0627\0632\0627\062A \0627\0644\0645\0639\062A\0645\062F\0629'),
'SELECT ',
'    ''Leave Taken: '' || lt.leave_type_name AS title,',
'    ''Total Days: '' || l.total_days || '' - Reason: '' || l.reason AS description,',
'    l.start_date AS event_date,',
'    ''fa-calendar'' AS icon,',
'    ''u-color-4'' AS css_class',
'FROM hr_leaves l',
'JOIN hr_leave_types lt ON l.leave_type_id = lt.leave_type_id',
'WHERE l.employee_id = :P14_EMPLOYEE_ID ',
'  AND l.status = ''APPROVED'''))
,p_template_component_type=>'REPORT'
,p_lazy_loading=>false
,p_plug_source_type=>'TMPL_THEME_42$TIMELINE'
,p_plug_query_num_rows=>15
,p_plug_query_num_rows_type=>'SET'
,p_show_total_row_count=>false
,p_landmark_type=>'region'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'APPLY_THEME_COLORS', 'Y',
  'AVATAR_ICON', 'fa-user',
