,p_region_template_options=>'#DEFAULT#:t-IRR-region--hideHeader js-addHiddenHeadingRoleDesc'
,p_plug_template=>2100526641005906379
,p_plug_display_sequence=>10
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- SELECT ',
'--     b.balance_id,',
'--     e.first_name || '' '' || e.last_name AS employee_name,',
'--     t.leave_type_name,',
'--     b.year,',
'--     NVL(b.used_days, 0) AS used_days',
'-- FROM hr_leave_balances b',
'-- LEFT JOIN hr_employees e ON b.employee_id = e.employee_id',
'-- LEFT JOIN hr_leave_types t ON b.leave_type_id = t.leave_type_id',
'SELECT ',
'    b.balance_id,',
'    e.first_name || '' '' || e.last_name AS employee_name,',
'    t.leave_type_name,',
'    b.year,',
'    NVL(t.max_days_per_year, 21) AS total_days,',
'    NVL(b.used_days, 0) AS used_days,',
'    (NVL(t.max_days_per_year, 21) - NVL(b.used_days, 0)) AS remaining_days',
'FROM hr_leave_balances b',
'LEFT JOIN hr_employees e ON b.employee_id = e.employee_id',
'LEFT JOIN hr_leave_types t ON b.leave_type_id = t.leave_type_id'))
,p_plug_source_type=>'NATIVE_IR'
,p_prn_page_header=>'Leave Balances'
);
