'-- .hr_employees e ON p.employee_id = e.employee_id',
'',
'-- SELECT ',
'--     p.payroll_id,',
'--     e.employee_code,',
'--     NVL(e.first_name || '' '' || e.last_name, ''N/A'') AS employee_name,',
'--     p.payroll_month || ''/'' || p.payroll_year AS pay_period,',
'--     p.basic_salary,',
'--     p.total_allowances,',
'--     p.insurance_amount,',
'--     p.tax_amount,',
'--     p.total_deductions,',
'--     p.net_salary,',
'--     p.status',
'-- FROM hr.hr_payroll p',
'-- LEFT JOIN hr.hr_employees e ON p.employee_id = e.employee_id',
'-- WHERE p.payroll_month = TO_NUMBER(SUBSTR(:P16_PAYROLL_MONTH, 1, 2))',
'--   AND p.payroll_year = TO_NUMBER(:P16_PAYROLL_YEAR)',
'',
'SELECT ',
'    p.payroll_id,',
'    e.employee_code,',
'    NVL(e.first_name || '' '' || e.last_name, ''N/A'') AS employee_name,',
'    p.payroll_month || ''/'' || p.payroll_year AS pay_period,',
'    p.basic_salary,',
'    p.total_allowances,',
'    p.insurance_amount,',
'    p.tax_amount,',
'    p.total_deductions,',
'    p.net_salary,',
'    p.status,',
'    ''Print Payslip'' AS print_payslip',
'FROM hr.hr_payroll p',
'LEFT JOIN hr.hr_employees e ON p.employee_id = e.employee_id',
'WHERE p.payroll_month = TO_NUMBER(SUBSTR(:P16_PAYROLL_MONTH, 1, 2))',
'  AND p.payroll_year = TO_NUMBER(:P16_PAYROLL_YEAR)'))
