prompt --application/pages/page_00019
begin
wwv_flow_imp_page.create_page(
 p_id=>19
,p_name=>'Employee Payslip'
,p_alias=>'EMPLOYEE-PAYSLIP'
,p_page_mode=>'MODAL'
,p_step_title=>'Employee Payslip'
,p_autocomplete_on_off=>'OFF'
,p_page_template_options=>'#DEFAULT#'
,p_dialog_resizable=>'Y'
,p_protection_level=>'C'
,p_page_component_map=>'10'
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(14493336604037421)
,p_plug_name=>'Payslip Details'
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>4072358936313175081
,p_plug_display_sequence=>20
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_pay hr.hr_payroll%ROWTYPE;',
'    v_emp hr.hr_employees%ROWTYPE;',
'    v_dept_name VARCHAR2(100) := ''N/A'';',
'    v_desg_title VARCHAR2(100) := ''N/A'';',
'BEGIN',
unistr('    -- \062C\0644\0628 \0628\064A\0627\0646\0627\062A \0627\0644\0631\0627\062A\0628 \0648\0627\0644\0645\0648\0638\0641'),
'    SELECT * INTO v_pay FROM hr.hr_payroll WHERE payroll_id = :P19_PAYROLL_ID;',
'    SELECT * INTO v_emp FROM hr.hr_employees WHERE employee_id = v_pay.employee_id;',
'    ',
unistr('    -- \062C\0644\0628 \0627\0633\0645 \0627\0644\0642\0633\0645'),
'    BEGIN',
'        SELECT department_name INTO v_dept_name FROM hr.hr_departments WHERE department_id = v_emp.department_id;',
'    EXCEPTION WHEN OTHERS THEN ',
'        v_dept_name := ''N/A'';',
'    END;',
'',
unistr('    -- \062C\0644\0628 \0627\0644\0645\0633\0645\0649 \0627\0644\0648\0638\064A\0641\064A (\062A\062C\0627\0648\0632 \0627\0633\0645 \0627\0644\0639\0645\0648\062F \0628\0645\0631\0648\0646\0629)'),
'    BEGIN',
'        EXECUTE IMMEDIATE ''SELECT designation_title FROM hr.hr_designations WHERE designation_id = :1'' ',
'        INTO v_desg_title USING v_emp.designation_id;',
'    EXCEPTION WHEN OTHERS THEN ',
'        v_desg_title := ''Employee'';',
'    END;',
'',
unistr('    -- \0637\0628\0627\0639\0629 \062A\0635\0645\064A\0645 \0627\0644\0640 Payslip \0628\0644\063A\0629 HTML'),
'    HTP.P(''<div style="width: 100%; max-width: 750px; margin: auto; padding: 25px; border: 2px solid #2c3e50; border-radius: 8px; font-family: Arial, sans-serif; background-color: #ffffff; color: #333;">'');',
'    ',
unistr('    -- Header \0627\0644\0634\0631\0643\0629'),
'    HTP.P(''  <div style="text-align: center; border-bottom: 2px solid #2c3e50; padding-bottom: 15px; margin-bottom: 20px;">'');',
'    HTP.P(''    <h2 style="margin: 0; color: #2c3e50;">ENTERPRISE HR MANAGEMENT SYSTEM</h2>'');',
unistr('    HTP.P(''    <h4 style="margin: 5px 0 10px 0; color: #7f8c8d;">PAYSLIP / \0643\0634\0641 \0645\0641\0631\062F\0627\062A \0627\0644\0645\0631\062A\0628</h4>'');'),
'    HTP.P(''    <span style="background: #eef2f5; padding: 4px 12px; border-radius: 12px; font-weight: bold;">Pay Period: '' || v_pay.payroll_month || '' / '' || v_pay.payroll_year || ''</span>'');',
'    HTP.P(''  </div>'');',
'',
unistr('    -- \0628\064A\0627\0646\0627\062A \0627\0644\0645\0648\0638\0641'),
'    HTP.P(''  <table style="width: 100%; margin-bottom: 20px; font-size: 14px; border-spacing: 0 8px;">'');',
'    HTP.P(''    <tr><td style="width:50%;"><strong>Employee Code:</strong> '' || v_emp.employee_code || ''</td><td style="width:50%;"><strong>Employee Name:</strong> '' || NVL(v_emp.first_name || '' '' || v_emp.last_name, ''N/A'') || ''</td></tr>'');',
'    HTP.P(''    <tr><td><strong>Department:</strong> '' || v_dept_name || ''</td><td><strong>Designation:</strong> '' || v_desg_title || ''</td></tr>'');',
'    HTP.P(''  </table>'');',
'',
unistr('    -- \062C\062F\0648\0644 \062A\0641\0627\0635\064A\0644 \0627\0644\0627\0633\062A\062D\0642\0627\0642\0627\062A \0648\0627\0644\0627\0633\062A\0642\0637\0627\0639\0627\062A'),
'    HTP.P(''  <table style="width: 100%; border-collapse: collapse; margin-bottom: 20px; font-size: 14px;" border="1" borderColor="#ddd">'');',
'    HTP.P(''    <tr style="background-color: #34495e; color: #ffffff; text-align: left;">'');',
unistr('    HTP.P(''      <th style="padding: 10px;">Earnings (\0627\0644\0627\0633\062A\062D\0642\0627\0642\0627\062A)</th>'');'),
'    HTP.P(''      <th style="padding: 10px; text-align: right;">Amount</th>'');',
