,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- select EMPLOYEE_ID,',
'--        EMPLOYEE_CODE,',
'--        FULL_NAME,',
'--        EMAIL,',
'--        PHONE,',
'--        DEPARTMENT_NAME,',
'--        DESIGNATION_TITLE,',
'--        BRANCH_NAME,',
'--        MANAGER_NAME,',
'--        JOINING_DATE,',
'--        BASIC_SALARY,',
'--        GROSS_SALARY,',
'--        STATUS',
'--   from V_HR_EMPLOYEE_DETAILS',
'-- SELECT ',
'--     employee_id,',
'--     full_name AS card_title,',
'--     designation_title AS card_subtitle,',
'--     department_name AS card_text,',
'--     status,',
'--     CASE status ',
'--         WHEN ''ACTIVE'' THEN ''u-success''',
'--         WHEN ''ON_LEAVE'' THEN ''u-warning''',
'--         ELSE ''u-danger''',
'--     END AS status_color,',
'--     email,',
'--     phone',
'-- FROM hr.v_hr_employee_details',
'',
'SELECT ',
'    employee_id,',
'    full_name,',
'    full_name AS card_title,',
'    designation_title,',
'    designation_title AS card_subtitle,',
'    department_name,',
'    department_name AS card_text,',
'    branch_name,',
'    status,',
'    CASE status ',
'        WHEN ''ACTIVE'' THEN ''u-success''',
'        WHEN ''ON_LEAVE'' THEN ''u-warning''',
'        ELSE ''u-danger''',
'    END AS status_color,',
'    email,',
'    phone,',
'    gross_salary',
'FROM hr.v_hr_employee_details'))
,p_query_order_by_type=>'ITEM'
,p_query_order_by=>'{ "itemName": "P21_ORDER_BY", "orderBys": [{"key":"FULL_NAME","expr":"\"FULL_NAME\" asc"},{"key":"DEPARTMENT_NAME","expr":"\"DEPARTMENT_NAME\" asc"},{"key":"STATUS","expr":"\"STATUS\" asc"}]}'
